/** Rehab stretches for each muscle of the anatomy map (the programme's own data). */
import { isListed } from '../../rehab/demoClips';
import { exerciseById } from '../../rehab/exercises';
import { STRETCHES } from '../../rehab/stretches';
import type { Anatomy } from './sheets';

export function stretchesFor(a: Anatomy): { id: string; title: string }[] {
  // The buccinator's stretch is one of the base exercises, not part of the video programme.
  const ids = a === 'buccinator' ? ['stretch-buccinator'] : STRETCHES.filter((p) => p.muscle === a).map((p) => p.id);
  return ids.flatMap((id) => {
    const e = exerciseById(id);
    return e && isListed(e) ? [{ id: e.id, title: e.title }] : [];
  });
}
